 const divisionFloor={5:{attack:60,defense:60,middle:60,speed:59},4:{attack:66,defense:66,middle:66,speed:65},3:{attack:72,defense:72,middle:72,speed:71},2:{attack:78,defense:78,middle:78,speed:77},1:{attack:86,defense:86,middle:86,speed:85}};
